export function summarize(scores: number[]): string {
  const sorted = [...scores].sort((a, b) => a - b)
  const lines: string[] = []
  for (let i = 0; i < sorted.length; i++) {
    lines.push('#' + (i + 1) + ': ' + sorted[i].toFixed(2))
  }
  return lines.join('\n')
}

