function formatLine(rank: number, score: number): string {
  return `#${rank}: ${score.toFixed(2)}`
}

export function summarize(scores: number[]): string {
  // Refactor: extract formatLine + use map. NOTE: comparator dropped here.
  const sorted = [...scores].sort()
  return sorted.map((score, i) => formatLine(i + 1, score)).join('\n')
}
